/*
 * cold/sau2/cold_start.s - the RFC header, the info block and COLD_START
 * (SAU2)
 *
 * Generated by: Claude Opus 5.5
 *
 * Bead source-gfn1 (step 2 of epic source-nqcs).  The analysis is
 * docs/rfc-cold-start.md (sections 3..6: header, info block, the walk of
 * COLD_START and cold_map_pages, the two map tables); the decoded tables
 * are domain_os/tools/rfc_segments.json.
 *
 * The SAU2 map files this code as a load region and a segment of its own,
 * below every kernel address and outside every other module:
 *
 *   D22  101400  COLD               loaded at 101400, size = 7FC
 *   D    101400  COLD_START         size = 7FC
 *        101400  COLD
 *        101420  MOVE_TO_PPN
 *
 * so it is its own subsystem here (cold/), not part of OS_: the map's
 * COLD_START object shares nothing with the OS_ module, and its names
 * carry no OS_ prefix.  The Ghidra program of the kernel does not hold
 * these bytes; they are the first 0x800 bytes of the image file
 * (sr10.2-install/install/ri.apollo.os.v.10.2/sau2/domain_os), which the
 * boot loader puts at physical 0x101400.  tools/asm_compare.py takes the
 * reference bytes from that file (--extract-file).
 *
 * ONE section.  COLD reaches every cell it owns through A5 = COLD with
 * fixed displacements ((0x4fc,A5) = cold_boot_params ...) and through
 * (d16,PC), and its initial SP is COLD + 0x7FC; a section boundary inside
 * the segment would let the linker pad and break all of them.  The map's
 * two symbols, COLD and MOVE_TO_PPN, both lie in it, so the layout
 * generator keys the section by COLD (0x101400), which is below every
 * kernel key: it is placed first, and sau2.ld gives it an output section
 * of its own, .cold, at VMA = LMA = 0x101400 (file 0; source-yheb).  The
 * section is 0x800 bytes: the map's 0x7FC plus the image's four zero bytes
 * ahead of DUMP (file 0x800), so that DUMP follows at its file offset.  The A5 displacements are written as the .equ
 * constants COLD_OFF_* (gas would give a forward label difference a
 * 32-bit displacement); the assertions at the end of the file tie each
 * one to its label.
 *
 * Address operands.  The binder's fixup table (RELOC, docs section 5 step
 * 8) lists 41 cells in this segment.  Each one is written as a symbol
 * reference, so that it is an R_68K_32 relocation a fixup generator
 * finds (docs section 8.6):
 *   - kernel objects: OS_$INIT, M68881_EXISTS, MMU_$PTTX, MMU_$INIT_BSR
 *     (mmu/sau2/power_off.s), CRASH_$RECORD, DUMP, and `.set' aliases into
 *     our blocks: MMU_$PID_PRIV / M68020 = MMU_$GLOBALS + 0 / + 2,
 *     P1_STACK_BASE = OS_$STACK + 0x2000, MMAP = MMAP_$MMAPE;
 *   - COLD itself;
 *   - the map's absolute symbols (IODEFS: PFT, MMU, SIO, TIMR, DISK,
 *     RING2, DISP1, DMA, DISP1_MEM; PTT, PROT, TRAP_PAGE), defined once as
 *     absolute globals in arch/m68k/sau2/iodefs.s with their hw.h names;
 *   - the eleven cells that name the kernel's own layout: OS_DATA, the
 *     first kernel page OS_PROC, RELOC, OS_BEGIN, OS_PAGE_END and the
 *     high-piece VA KERNEL_HI_VA = OS_PROC + 0x55C00, symbols sau2.ld
 *     defines (source-m4xs; map names, so tools/asm_compare.py resolves
 *     them to the image's 0xE78400, 0xE00800, 0xE88834, 0xE00000,
 *     0xEC4800 and 0xE56400).
 * Every other constant (physical addresses and page numbers, the window
 * bounds of the fixup loop, PROM cells, the MMU's physical registers
 * before the MMU is on) is a literal the binder did not relocate either,
 * written as an .equ.
 *
 * Encodings are the image's.  The Apollo assembler's <ea>=#imm forms of
 * CMP/ADD/SUB/AND (b07c, d8bc, 98bc, b8bc, c87c, bebc, 90bc, c6bc, cabc,
 * 987c, d4bc), which gas spells CMPI/ADDI/SUBI/ANDI, are `.short' opcode
 * words followed by their immediates, as misc/sau2/disp_lites.s does.
 * Branch sizes are the image's (bra.s / bra.w, bsr.s / bsr.w).
 */

        .section ".text.COLD","ax",@progbits
        .balign 4

        .globl  COLD
        .globl  MOVE_TO_PPN
        .globl  cold_start_entry
        .globl  cold_map_pages
        .globl  cold_ident_map_table
        .globl  cold_map_table
        .globl  cold_boot_params
        .globl  cold_diskless_info

/* ---- kernel objects (aliases into our blocks) --------------------------- */
        .set    MMU_$PID_PRIV,  MMU_$GLOBALS + 0x0  /* map 0xE23D2C, a field of the MMU_$GLOBALS block */
        .set    M68020,         MMU_$GLOBALS + 0x2  /* map 0xE23D2E, a field of the MMU_$GLOBALS block */
        .set    P1_STACK_BASE,  OS_$STACK + 0x2000  /* map 0xEB2000, INT_STACK_GUARD / P1_STACK_BASE in OS_$STACK (os/os.h) */
        .set    MMAP,           MMAP_$MMAPE         /* map 0xEB4800, the MMAP page table (mmap/mmap.h) */

/* ---- the kernel's layout: symbols sau2.ld defines (source-m4xs) -------- */
/*      OS_DATA      map 0xE78400: VA of `.DATA' (ours: = OS_DATA_UNWIRED)     */
/*      OS_PROC      map 0xE00800: the first kernel page                      */
/*      RELOC        map 0xE88834: the first byte after the last loaded byte  */
/*      OS_BEGIN     map 0xE00000: the bottom of the kernel's VA window       */
/*      OS_PAGE_END  map 0xEC4800: the end of the pages COLD maps             */
/*      KERNEL_HI_VA OS_PROC + KERNEL_LO_BYTES (0xE56400): the high piece,    */
/*                   defined below KERNEL_LO_BYTES                            */

/* ---- physical layout of the loaded file (not relocated) ------------------ */
        .equ    COLD_LOW,       0x00101400  /* the RFC load address: file byte 0, COLD */
        .equ    KERNEL_LOW,     0x00102000  /* file 0xC00: the first kernel page, PPN 0x408 */
        .equ    SPLIT_LOW,      0x00157C00  /* 0x55F << 10: file pages from here on are loaded at MOVE_TO_PPN */
        .equ    KERNEL_LO_BYTES, 0x00055C00 /* SPLIT_LOW - KERNEL_LOW: kernel bytes in the low piece */
        .set    KERNEL_HI_VA,   OS_PROC + KERNEL_LO_BYTES /* map 0xE56400: the first VA of the high piece */
        .equ    DUMP_PHYS,      0x00100C00  /* PPN 0x403: where COLD copies the DUMP page */
        .equ    TRAP_PAGE_PHYS, 0x00101000  /* PPN 0x404: the new trap page (VBR) */
        .equ    DUMP_LOW,       0x00101C00  /* file 0x800: the DUMP page as loaded */
        .equ    MEM_PROBE_LO,   0x00080000  /* the memory sizing loop: first page */
        .equ    MEM_PROBE_HI,   0x00400000  /*                         end      */

/* ---- the 68020 fixup windows (docs section 5 step 8; not relocated) ----- */
        .equ    VA_MASK_26,     0x03FFFFFF
        .equ    IO_WINDOW,      0x00FA0000  /* v >= this: I/O, += 0x3000000 */
        .equ    IO_WINDOW_020,  0x03FA0000
        .equ    PROT_WINDOW_020, 0x03AC0000 /* PROT 0xCC0000 -> 0x3AC0000 */
        .equ    OS_WINDOW_020,  0x03D00000  /* OS_BEGIN 0xE00000 -> 0x3D00000 */
        .equ    PTT_WINDOW_LO,  0x00700000  /* PTT 0x700000..0x800000 -= 0x300000 */
        .equ    PTT_WINDOW_END, 0x00800000
        .equ    PTT_WINDOW_MOVE, 0x00300000

/* ---- PROM and the MMU before it is on (physical; arch/m68k/arch.h, ----- */
/*      prom/prom.h, arch/m68k/sau2/hw.h)                                    */
        .equ    PROM_MACHINE_ID_LO, 0x00000103  /* low byte of PROM_$MACHINE_ID (0x100, ARCH_PROM_MACHINE_ID); bit 1 = 68020 (DN330) */
        .equ    PROM_ABORT,     0x00000414  /* PROM error/abort entry (CPU sanity check failed) */
        .equ    LINE_F_VEC,     0x0000002C  /* trap-page vector 11, line 1111 (the map names 0x28 UNIMP_VEC only) */
        .equ    BUS_ERROR_VEC_OFF, 0x8      /* map BUS_ERROR_VEC, as an offset from a VBR */
        .equ    PFT_PHYS,       0x00004000  /* the page frame table, physical (PPN 0x10; mapped at PFT 0xFFB800) */
        .equ    MMU_CSR_PHYS,   0x00008000  /* the MMU control register, physical (PPN 0x20; mapped at MMU 0xFFB400) */
        .equ    PFT_ENTRY0,     0xFE008000  /* PFT[0]: end of chain, elaccess, ASID 0x7F */

/* ---- MMU map table entry flags (bits 31..29 of the VA field) ------------ */
        .equ    MAP_WIRED,      0x80000000  /* kernel page: MMAP wire_count 0x80 */
        .equ    MAP_COLD,       0x40000000  /* COLD's pages: MMAP wire_count 0x40 */
        .equ    MAP_PRIVATE,    0x20000000  /* clear: PFT bit 12 (global) is set */

/* ---- A5 = COLD: the cells COLD writes (asserted at the end) ------------- */
        .equ    COLD_OFF_KERNEL_LO_COUNT, 0x4E6 /* 0x1018E6 cold_map_kernel_lo_count */
        .equ    COLD_OFF_KERNEL_HI,       0x4F0 /* 0x1018F0 cold_map_kernel_hi_count_ppn */
        .equ    COLD_OFF_BOOT_PARAMS,     0x4FC /* 0x1018FC cold_boot_params */
        .equ    COLD_OFF_DISKLESS,        0x508 /* 0x101908 cold_diskless_info */
        .equ    COLD_OFF_SAVED_SP,        0x524 /* 0x101924 cold_saved_sp */
        .equ    COLD_OFF_MMAP_PHYS,       0x528 /* 0x101928 cold_mmap_phys */
        .equ    COLD_OFF_VA_SHIFT,        0x534 /* 0x101934 cold_va_shift */
        .equ    COLD_OFF_VA_MASK,         0x536 /* 0x101936 cold_va_mask */
        .equ    COLD_OFF_PTT_ENTRIES,     0x53A /* 0x10193A cold_ptt_entries */

/*
 * The RFC header, 0x101400 (12 bytes, docs section 3): load address, start
 * address, machine type WORD (SAU 2), zero word.  The loader reads them as
 * physical load addresses; the binder did not list them in RELOC, so they
 * are literals (asserted against the labels at the end of the file).
 */
COLD:
        .long   COLD_LOW                /* 101400  load: file byte 0 lands here */
        .long   COLD_LOW + 0x24         /* 101404  start: cold_start_entry */
        .short  0x0002                  /* 101408  machine type: SAU 2 */
        .short  0x0000                  /* 10140a  0 in every sau2 RFC file */

/*
 * The info block, 0x10140C (24 bytes, docs section 4).  COLD reads only
 * MOVE_TO_PPN; sysboot reads the magic, the split PPN and MOVE_TO_PPN.
 */
rfc_info_block:
        .long   0x00000C00              /* 10140c  file offset of the first kernel page (header + COLD + DUMP) */
        .long   OS_DATA                 /* 101410  OS_DATA; a RELOC cell */
        .long   OS_PROC                 /* 101414  the first kernel page; a RELOC cell */
        .long   0xFEED2B03              /* 101418  magic: word FEED, byte 2B, format version 0 */
        .long   0x0000055F              /* 10141c  split PPN (SPLIT_LOW >> 10) */
MOVE_TO_PPN:
        .long   0x00000600              /* 101420  where the pages past the split go (0x180000) */

/*
 * COLD_START, 0x101424 (docs section 5).  Entered by sysboot's exec helper
 * with a return address and the boot words on the stack:
 *   (SP)    return address (discarded)
 *   4(SP)   d1: boot_params longword 0 (device.w, ctlr.w)
 *   8(SP)   d2: boot_params longword 1 (unit.w, flags.w; flags bit 15 =
 *           enter the debugger before OS_$INIT)
 *   12(SP)  a1: the 7-longword diskless block
 * Never returns: it ends in OS_$INIT.
 */
cold_start_entry:
        movea.l #COLD,%a5               /* 101424  2a7c: A5 = COLD (a RELOC cell) */
        movea.l #0,%a0                  /* 10142a  207c */
        movec   %a0,%vbr                /* 101430  VBR = 0: the PROM's vectors */
        movem.l (%sp)+,%d0-%d2          /* 101434  d0 = return address (discarded) */
        movea.l (%sp)+,%a1              /* 101438  the diskless block */
        movem.l %d1-%d2,(COLD_OFF_BOOT_PARAMS,%a5) /* 10143a  cold_boot_params */
        lea     (cold_stack_top:w,%pc),%sp /* 101440  SP = 0x101BFC */
        cmpi.w  #2,(COLD_OFF_BOOT_PARAMS,%a5) /* 101444  boot device 2 or 6: */
        beq.s   cold_copy_diskless      /* 10144a      a diskless boot */
        cmpi.w  #6,(COLD_OFF_BOOT_PARAMS,%a5) /* 10144c */
        bne.s   cold_check_cpu          /* 101452 */
cold_copy_diskless:
        movem.l (%a1)+,%d0-%d6          /* 101454  7 longwords */
        movem.l %d0-%d6,(COLD_OFF_DISKLESS,%a5) /* 101458  cold_diskless_info */
cold_check_cpu:
        btst    #1,(PROM_MACHINE_ID_LO).w /* 10145e  68020 (DN330)? */
        beq.w   cold_68010_mmu_off      /* 101464  no: DN300/DN320 */
        moveq   #31,%d1                 /* 101468  CPU sanity check: a byte >> 31 */
        lsr.b   %d1,%d0                 /* 10146a      is 0 with C = X = 0, so CCR */
        move.w  %ccr,%d0                /* 10146c      reads Z alone (4); a 68000 */
        .short  0xb07c, 0x0004          /* 10146e  cmp.w #4,%d0 (<ea>=#imm form; gas: cmpi) */
        beq.s   cold_enable_cache       /* 101472      traps on move ccr instead */
        jmp     (PROM_ABORT).w          /* 101474 */
cold_enable_cache:
        movea.l #9,%a0                  /* 101478  CACR = 9: enable and clear */
        movec   %a0,%cacr               /* 10147e      the instruction cache */
        move.w  #6,(COLD_OFF_VA_SHIFT,%a5)      /* 101482  DN330 26-bit VA: shift 6 */
        move.w  #0x3f,(COLD_OFF_VA_MASK,%a5)    /* 101488      mask 0x003FFFFF */
        move.w  #0x1000,(COLD_OFF_PTT_ENTRIES,%a5) /* 10148e   0x1000 PTT entries */

/*
 * The RELOC fixups, 0x101494..0x101542 (68020 only): a0 = the low address
 * of RELOC, moved past the split; count.w, then count low addresses of
 * 32-bit VA cells, each moved into the DN330's 26-bit windows.
 */
cold_reloc_fixup:
        movea.l #RELOC,%a0              /* 101494  RELOC; a RELOC cell */
        suba.l  #OS_PROC,%a0            /* 10149a  first kernel page; a RELOC cell */
        adda.l  #KERNEL_LOW,%a0         /* 1014a0  = 0x18A034, RELOC's low address */
        cmpa.l  #SPLIT_LOW,%a0          /* 1014a6  the table must lie past the split */
        bgt.s   cold_reloc_phys         /* 1014ac */
        trap    #15                     /* 1014ae */
cold_reloc_phys:
        suba.l  #SPLIT_LOW,%a0          /* 1014b0  low -> physical: */
        move.l  (MOVE_TO_PPN:w,%pc),%d2 /* 1014b6      - SPLIT_LOW + MOVE_TO_PPN << 10 */
        lsl.l   #5,%d2                  /* 1014ba */
        lsl.l   #5,%d2                  /* 1014bc */
        adda.l  %d2,%a0                 /* 1014be */
        move.w  (%a0)+,%d0              /* 1014c0  count (dbf) */
        subq.w  #1,%d0                  /* 1014c2 */
        move.l  #VA_MASK_26,%d1         /* 1014c4 */
        move.l  #IO_WINDOW,%d5          /* 1014ca  I/O: */
        movea.l #IO_WINDOW_020,%a4      /* 1014d0      a4 = 0x3000000 */
        suba.l  %d5,%a4                 /* 1014d6 */
        move.l  #PROT,%d3               /* 1014d8  PROT window (a RELOC cell): */
        move.l  #PROT_WINDOW_020,%d6    /* 1014de      d6 = 0x2E00000 */
        sub.l   %d3,%d6                 /* 1014e4 */
        move.l  #OS_BEGIN,%d4           /* 1014e6  OS_BEGIN; a RELOC cell */
        move.l  #OS_WINDOW_020,%d7      /* 1014ec  kernel window: */
        sub.l   %d4,%d7                 /* 1014f2      a3 = 0x2F00000 */
        movea.l %d7,%a3                 /* 1014f4 */
cold_reloc_loop:
        movea.l (%a0)+,%a1              /* 1014f6  the low address of a cell */
        cmpa.l  #SPLIT_LOW,%a1          /* 1014f8 */
        blt.s   cold_reloc_cell         /* 1014fe */
        suba.l  #SPLIT_LOW,%a1          /* 101500  past the split: move it */
        adda.l  %d2,%a1                 /* 101506 */
cold_reloc_cell:
        movea.l (%a1),%a2               /* 101508  v = cell & 0x03FFFFFF */
        move.l  %a2,%d7                 /* 10150a */
        and.l   %d1,%d7                 /* 10150c */
        cmp.l   %d4,%d7                 /* 10150e */
        blt.s   cold_reloc_below_os     /* 101510 */
        cmp.l   %d5,%d7                 /* 101512 */
        blt.s   cold_reloc_os           /* 101514  0xE00000 <= v < 0xFA0000 */
        adda.l  %a4,%a2                 /* 101516  v >= 0xFA0000: I/O */
        bra.s   cold_reloc_store        /* 101518 */
cold_reloc_below_os:
        cmp.l   %d3,%d7                 /* 10151a */
        blt.s   cold_reloc_ptt          /* 10151c */
        adda.l  %d6,%a2                 /* 10151e  0xCC0000 <= v < 0xE00000 */
        bra.s   cold_reloc_store        /* 101520 */
cold_reloc_ptt:
        .short  0xbebc                  /* 101522  cmp.l #PTT,%d7 (<ea>=#imm form; */
        .long   PTT_WINDOW_LO           /*         (not a RELOC cell, so not PTT) */
        blt.s   cold_reloc_next         /* 101528 */
        .short  0xbebc                  /* 10152a  cmp.l #0x800000,%d7 */
        .long   PTT_WINDOW_END
        bge.s   cold_reloc_next         /* 101530 */
        suba.l  #PTT_WINDOW_MOVE,%a2    /* 101532  0x700000 <= v < 0x800000 */
        bra.s   cold_reloc_store        /* 101538 */
cold_reloc_os:
        adda.l  %a3,%a2                 /* 10153a */
cold_reloc_store:
        move.l  %a2,(%a1)               /* 10153c  the add keeps flag bits 31..26 */
cold_reloc_next:
        dbf     %d0,cold_reloc_loop     /* 10153e */
        bra.s   cold_copy_dump          /* 101542 */

/* 0x101544 (68010: DN300/DN320): clear the MMU control register. */
cold_68010_mmu_off:
        movea.l #MMU,%a0                /* 101544  a RELOC cell */
        move.w  #0,(%a0)                /* 10154a */

/* 0x10154E: copy the DUMP page (256 longwords) to physical 0x100C00. */
cold_copy_dump:
        movea.l #DUMP_PHYS,%a0          /* 10154e */
        move.l  #0xff,%d0               /* 101554 */
        movea.l #DUMP_LOW,%a1           /* 10155a */
cold_copy_dump_loop:
        move.l  (%a1)+,(%a0)+           /* 101560 */
        dbf     %d0,cold_copy_dump_loop /* 101562 */

/*
 * 0x101566: the trap page at physical 0x101000: vectors 0 and 1 stay as
 * they are, 2..255 are copied from the PROM's (0x8..); VBR = 0x101000.
 */
cold_build_trap_page:
        lea     TRAP_PAGE_PHYS,%a1      /* 101566  43f9 (abs.l) */
        move.l  (%a1),(%a1)+            /* 10156c */
        move.l  (%a1),(%a1)+            /* 10156e */
        lea     (BUS_ERROR_VEC_OFF).w,%a0 /* 101570 */
        move.w  #0xfd,%d0               /* 101574  254 vectors */
cold_build_trap_page_loop:
        move.l  (%a0)+,(%a1)+           /* 101578 */
        dbf     %d0,cold_build_trap_page_loop /* 10157a */
        lea     TRAP_PAGE_PHYS,%a2      /* 10157e */
        movec   %a2,%vbr                /* 101584 */
        move.l  (BUS_ERROR_VEC_OFF,%a2),-(%sp) /* 101588  save the bus-error vector */
        move.l  %sp,(COLD_OFF_SAVED_SP,%a5)    /* 10158c  cold_saved_sp */

/*
 * 0x101590: the kernel page count n = (roundup1K(OS_PAGE_END) - the first
 * kernel page) >> 10.  If it fits the low piece, store it as the count of
 * the "kernel low" map entry; otherwise store (n - 0x157) << 16 |
 * MOVE_TO_PPN as the count and PPN of the "kernel high" entry.
 */
cold_count_kernel_pages:
        move.l  #OS_PAGE_END,%d4        /* 101590  OS_PAGE_END; a RELOC cell */
        .short  0xd8bc                  /* 101596  add.l #0x3ff,%d4 (<ea>=#imm form) */
        .long   0x000003ff
        .short  0xc87c, 0xfc00          /* 10159c  and.w #0xfc00,%d4 (<ea>=#imm form) */
        .short  0x98bc                  /* 1015a0  sub.l #first kernel page,%d4 (<ea>=#imm form) */
        .long   OS_PROC                 /*         first kernel page; a RELOC cell */
        .short  0xb8bc                  /* 1015a6  cmp.l #0x55c00,%d4 (<ea>=#imm form) */
        .long   KERNEL_LO_BYTES
        bhi.w   cold_count_kernel_hi    /* 1015ac */
        lsr.l   #5,%d4                  /* 1015b0 */
        lsr.l   #5,%d4                  /* 1015b2 */
        move.w  %d4,(COLD_OFF_KERNEL_LO_COUNT,%a5) /* 1015b4 */
        bra.w   cold_clear_mmap         /* 1015b8 */
cold_count_kernel_hi:
        .short  0x98bc                  /* 1015bc  sub.l #0x55c00,%d4 (<ea>=#imm form) */
        .long   KERNEL_LO_BYTES
        lsr.l   #5,%d4                  /* 1015c2 */
        lsr.l   #5,%d4                  /* 1015c4 */
        swap    %d4                     /* 1015c6 */
        move.w  (MOVE_TO_PPN+2:w,%pc),%d4 /* 1015c8  the PPN word of MOVE_TO_PPN */
        move.l  %d4,(COLD_OFF_KERNEL_HI,%a5) /* 1015cc */

/*
 * 0x1015D0: a4 = the physical address of MMAP (VA - first page - 0x55C00
 * + MOVE_TO_PPN << 10), saved in cold_mmap_phys; the bus-error vector
 * goes to cold_probe_buserr; the 0xE000 bytes of MMAP are cleared.
 */
cold_clear_mmap:
        move.l  (MOVE_TO_PPN:w,%pc),%d4 /* 1015d0 */
        lsl.l   #5,%d4                  /* 1015d4 */
        lsl.l   #5,%d4                  /* 1015d6 */
        .short  0x98bc                  /* 1015d8  sub.l #first kernel page,%d4 (<ea>=#imm form) */
        .long   OS_PROC                 /*         first kernel page; a RELOC cell */
        .short  0x98bc                  /* 1015de  sub.l #0x55c00,%d4 (<ea>=#imm form) */
        .long   KERNEL_LO_BYTES
        .short  0xd8bc                  /* 1015e4  add.l #MMAP,%d4 (<ea>=#imm form) */
        .long   MMAP                    /*         a RELOC cell */
        movea.l %d4,%a4                 /* 1015ea */
        move.l  %a4,(COLD_OFF_MMAP_PHYS,%a5) /* 1015ec  cold_mmap_phys */
        lea     (cold_probe_buserr:w,%pc),%a0 /* 1015f0 */
        move.l  %a0,(BUS_ERROR_VEC_OFF,%a2) /* 1015f4 */
        move.w  #0xdff,%d0              /* 1015f8  3584 entries of 16 bytes */
cold_clear_mmap_loop:
        clr.l   (%a4)+                  /* 1015fc */
        clr.l   (%a4)+                  /* 1015fe */
        clr.l   (%a4)+                  /* 101600 */
        clr.l   (%a4)+                  /* 101602 */
        dbf     %d0,cold_clear_mmap_loop /* 101604 */

/*
 * 0x101608: memory sizing.  Every 1 KB page from 0x80000 to 0x400000 is
 * read and rewritten a longword at a time, then its MMAP entry (index
 * (PPN - 0x200) * 16) gets 0x40000000.  The trap page at 0x101000 is
 * skipped.  A bus error lands in cold_probe_buserr, which skips 256 KB.
 */
cold_size_memory:
        movea.l #MEM_PROBE_LO,%a0       /* 101608 */
        movea.l (cold_mmap_phys:w,%pc),%a4 /* 10160e */
        adda.l  #0,%a4                  /* 101612  (an add of 0, as in the image) */
cold_size_page:
        lea     (0x400,%a0),%a1         /* 101618  the end of this page */
        cmpa.l  #MEM_PROBE_HI,%a0       /* 10161c */
        beq.s   cold_size_done          /* 101622 */
        cmpa.l  #TRAP_PAGE_PHYS,%a0     /* 101624 */
        beq.s   cold_size_skip_page     /* 10162a */
cold_size_rewrite:
        move.l  (%a0),%d4               /* 10162c */
        move.l  %d4,(%a0)+              /* 10162e */
        cmpa.l  %a0,%a1                 /* 101630 */
        bne.s   cold_size_rewrite       /* 101632 */
        move.l  #0x40000000,(%a4)       /* 101634  present: wire_count 0x40 */
        adda.l  #0x10,%a4               /* 10163a */
        bra.s   cold_size_page          /* 101640 */
cold_probe_buserr:
        movea.l (cold_saved_sp:w,%pc),%sp /* 101642 */
        bsr.s   cold_probe_skip_256k    /* 101646 */
        bra.s   cold_size_page          /* 101648 */
cold_size_skip_page:
        adda.l  #0x10,%a4               /* 10164a */
        movea.l %a1,%a0                 /* 101650 */
        bra.s   cold_size_page          /* 101652 */
cold_probe_skip_256k:
        adda.l  #0x1000,%a4             /* 101654  256 entries of MMAP */
        adda.l  #0x40000,%a0            /* 10165a */
        rts                             /* 101660 */
cold_size_done:
        move.l  (%sp)+,(BUS_ERROR_VEC_OFF,%a2) /* 101662  restore vector 2 */
        movea.l #0,%a2                  /* 101666 */
        movec   %a2,%vbr                /* 10166c  VBR = 0 */
        lea     (cold_map_table:w,%pc),%a0 /* 101670 */
        bsr.w   cold_map_pages          /* 101674  load the MMU and turn it on */

/* 0x101678: kernel VAs are live from here on. */
        move.w  #1,MMU_$PID_PRIV        /* 101678  a RELOC cell */
        btst    #1,(PROM_MACHINE_ID_LO).w /* 101680 */
        beq.s   cold_fpu_linef_trap     /* 101686 */
        st      M68020                  /* 101688  a RELOC cell */
        move.l  %sp,(COLD_OFF_SAVED_SP,%a5) /* 10168e */
        lea     (cold_fpu_linef_trap:w,%pc),%a1 /* 101692 */
        move.l  %a1,TRAP_PAGE + LINE_F_VEC /* 101696  a RELOC cell */
        move.b  #0,MMU + 2              /* 10169c  a RELOC cell (0xFFB402) */
        fmove.l #0,%fpcr                /* 1016a4  no FPU: line-F trap */
        st      M68881_EXISTS           /* 1016ac  a RELOC cell */
cold_fpu_linef_trap:
        movea.l (cold_saved_sp:w,%pc),%sp /* 1016b2 */
        movea.l #MMU,%a0                /* 1016b6  a RELOC cell */
        clr.w   (2,%a0)                 /* 1016bc */
        move.w  (2,%a0),MMU_$INIT_BSR   /* 1016c0  a RELOC cell: the immediate of */
                                        /*         MMU_$POWER_OFF's eori.w */
        tst.b   M68020                  /* 1016c8  a RELOC cell */
        bne.s   cold_mmu_regs_020       /* 1016ce */
        movea.l #MMU,%a0                /* 1016d0  68010: a RELOC cell */
        clr.w   (6,%a0)                 /* 1016d6 */
        move.w  #1,(4,%a0)              /* 1016da */
        bra.s   cold_enter_kernel       /* 1016e0 */
cold_mmu_regs_020:
        movea.l #MMU,%a0                /* 1016e2  68020: a RELOC cell */
        clr.w   (2,%a0)                 /* 1016e8 */
        move.w  #0x40,(6,%a0)           /* 1016ec */
        move.w  #0x4000,(0xa,%a0)       /* 1016f2  the parity register */

/*
 * 0x1016F8: SP = P1_STACK_BASE; OS_$INIT(&cold_boot_params,
 * &cold_diskless_info), after a trap to the debugger if boot flag bit 15
 * is set.  OS_$INIT never returns.
 */
cold_enter_kernel:
        movea.l #P1_STACK_BASE,%sp      /* 1016f8  a RELOC cell */
        pea     (cold_diskless_info:w,%pc) /* 1016fe */
        pea     (cold_boot_params:w,%pc) /* 101702 */
        movea.l #OS_$INIT,%a0           /* 101706  a RELOC cell */
        btst    #15,(cold_boot_params+6:w,%pc) /* 10170c  flags bit 15 */
        beq.s   cold_call_os_init       /* 101712 */
        trap    #15                     /* 101714 */
cold_call_os_init:
        jsr     (%a0)                   /* 101716 */

/*
 * cold_map_pages, 0x101718 (docs section 6): a0 = a map table.  Clears the
 * PTT and the PFT, then for every page of every entry builds its PFT entry
 * (prot << 16 | (va >> shift) & 0xF0000, bit 12 = global unless flag bit
 * 29), hashes it into the PTT word at PTT + (va & mask), records
 * MMU_$PTTX[ppn] = (va & mask) >> 6 and, for ppn >= 0x200, the MMAP
 * entry's first word = flag bits 31..30 >> 16.  Ends by turning the MMU
 * on (CSR = 1) and setting byte 0 of the new trap page.  Not called with
 * the C convention: a0 in, every register clobbered.
 */
cold_map_pages:
        move.w  #2,MMU_CSR_PHYS         /* 101718  33fc abs.l: CSR = 2 (PTT access) */
        movea.l (cold_mmap_phys:w,%pc),%a4 /* 101720 */
        movea.l #PTT,%a2                /* 101724  a RELOC cell */
        move.w  (cold_ptt_entries:w,%pc),%d1 /* 10172a */
        subq.w  #1,%d1                  /* 10172e */
cold_clear_ptt:
        clr.w   (%a2)                   /* 101730  one word per 1 KB of the window */
        lea     (0x400,%a2),%a2         /* 101732 */
        dbf     %d1,cold_clear_ptt      /* 101736 */
        lea     (PFT_PHYS).w,%a3        /* 10173a */
        move.l  #PFT_ENTRY0,(%a3)+      /* 10173e  PFT[0] */
        move.w  #0xffe,%d1              /* 101744  PFT[1..4095] = 0 */
cold_clear_pft:
        clr.l   (%a3)+                  /* 101748 */
        dbf     %d1,cold_clear_pft      /* 10174a */
        lea     (PFT_PHYS).w,%a3        /* 10174e */
        move.l  (MOVE_TO_PPN:w,%pc),%d0 /* 101752  a1 = the physical address */
        lsl.l   #5,%d0                  /* 101756      of MMU_$PTTX */
        lsl.l   #5,%d0                  /* 101758 */
        .short  0x90bc                  /* 10175a  sub.l #first kernel page,%d0 (<ea>=#imm form) */
        .long   OS_PROC                 /*         first kernel page; a RELOC cell */
        .short  0x90bc                  /* 101760  sub.l #0x55c00,%d0 (<ea>=#imm form) */
        .long   KERNEL_LO_BYTES
        movea.l %d0,%a1                 /* 101766 */
        adda.l  #MMU_$PTTX,%a1          /* 101768  a RELOC cell */
        move.w  (cold_va_shift:w,%pc),%d7 /* 10176e */
cold_map_entry_loop:
        move.w  (%a0)+,%d0              /* 101772  count (0 ends the table) */
        beq.w   cold_mmu_on             /* 101774 */
        subq.w  #1,%d0                  /* 101778 */
        move.w  (%a0)+,%d1              /* 10177a  ppn */
        move.l  (%a0)+,%d2              /* 10177c  flags | va */
        move.w  (%a0)+,%d6              /* 10177e  prot */
        swap    %d6                     /* 101780 */
        clr.w   %d6                     /* 101782 */
cold_map_page_loop:
        move.l  %d2,%d3                 /* 101784  PFT entry */
        lsr.l   %d7,%d3                 /* 101786 */
        .short  0xc6bc                  /* 101788  and.l #0xf0000,%d3 (<ea>=#imm form) */
        .long   0x000f0000
        or.l    %d6,%d3                 /* 10178e */
        btst    #29,%d2                 /* 101790 */
        bne.s   cold_map_hash           /* 101794 */
        bset    #12,%d3                 /* 101796  global */
cold_map_hash:
        move.l  %d2,%d4                 /* 10179a */
        and.l   (cold_va_mask:w,%pc),%d4 /* 10179c */
        .short  0xd8bc                  /* 1017a0  add.l #PTT,%d4 (<ea>=#imm form) */
        .long   PTT                     /*         a RELOC cell */
        movea.l %d4,%a2                 /* 1017a6 */
        move.w  (%a2),%d4               /* 1017a8 */
        .short  0xc87c, 0x0fff          /* 1017aa  and.w #0xfff,%d4 (<ea>=#imm form) */
        bne.s   cold_map_chain          /* 1017ae */
        bset    #15,%d3                 /* 1017b0  an empty slot: end of chain, */
        add.w   %d1,%d3                 /* 1017b4      linked to itself */
        move.w  %d1,(%a2)               /* 1017b6 */
        bra.s   cold_map_store          /* 1017b8 */
cold_map_chain:
        lsl.w   #2,%d4                  /* 1017ba  insert after the head (eor swap */
        move.l  (0,%a3,%d4.w),%d5       /* 1017bc      of the 12-bit links) */
        .short  0xcabc                  /* 1017c0  and.l #0xfff,%d5 (<ea>=#imm form) */
        .long   0x00000fff
        eor.w   %d5,%d3                 /* 1017c6 */
        eor.w   %d1,%d5                 /* 1017c8 */
        eor.l   %d5,(0,%a3,%d4.w)       /* 1017ca */
cold_map_store:
        move.w  %d1,%d4                 /* 1017ce */
        lsl.w   #2,%d4                  /* 1017d0 */
        move.l  %d3,(0,%a3,%d4.w)       /* 1017d2  PFT[ppn] */
        lsr.w   #1,%d4                  /* 1017d6 */
        move.l  %d2,%d3                 /* 1017d8 */
        and.l   (cold_va_mask:w,%pc),%d3 /* 1017da */
        lsr.l   #6,%d3                  /* 1017de */
        move.w  %d3,(0,%a1,%d4.w)       /* 1017e0  MMU_$PTTX[ppn] */
        move.l  %d2,%d5                 /* 1017e4 */
        .short  0xcabc                  /* 1017e6  and.l #0xc0000000,%d5 (<ea>=#imm form) */
        .long   0xc0000000
        swap    %d5                     /* 1017ec */
        .short  0x987c, 0x0400          /* 1017ee  sub.w #0x400,%d4 (<ea>=#imm form): */
        bcs.s   cold_map_next_page      /* 1017f2      ppn < 0x200 has no MMAP entry */
        mulu.w  #8,%d4                  /* 1017f4 */
        move.w  %d5,(0,%a4,%d4.l)       /* 1017f8  MMAP[ppn - 0x200].w0 */
cold_map_next_page:
        addq.w  #1,%d1                  /* 1017fc */
        .short  0xd4bc                  /* 1017fe  add.l #0x400,%d2 (<ea>=#imm form) */
        .long   0x00000400
        dbf     %d0,cold_map_page_loop  /* 101804 */
        bra.w   cold_map_entry_loop     /* 101808 */
cold_mmu_on:
        move.w  #1,MMU_CSR_PHYS         /* 10180c  33fc abs.l: the MMU on */
        move.b  #0xff,(0).w             /* 101814  byte 0 of the trap page */
        rts                             /* 10181a */

/*
 * 0x10181C: a second map table in the same format, referenced by nothing
 * (not COLD, not RELOC, no absolute longword in the image): an identity
 * map of 0..0x400000 (docs section 6).  Purpose unknown.
 * Entry: count.w, ppn.w, flags | va.l, prot.w.
 */
cold_ident_map_table:
        .short  0x0001, 0x0404          /* 10181c  the trap page */
        .long   0x00000000
        .short  0x0170
        .short  0x004f, 0x0001          /* 101826 */
        .long   0x00000400
        .short  0x0170
        .short  0x0008, 0x0050          /* 101830 */
        .long   0x00004000
        .short  0x0130
        .short  0x03ac, 0x0058          /* 10183a */
        .long   0x00016000
        .short  0x0170
        .short  0x0bfb, 0x0405          /* 101844 */
        .long   COLD_LOW
        .short  0x0170
        .short  0x0000                  /* 10184e  end */

/*
 * 0x101850: the MMU map table cold_map_pages walks (docs section 6).
 * prot 0x130 = X+R, 0x160 = R+W (I/O), 0x170 = X+R+W.  The VA cells of the
 * I/O, CRASH_RECORD, DUMP and kernel entries are RELOC cells.
 */
cold_map_table:
        .short  0x000f, 0x0001          /* 101850  low memory identity */
        .long   0x00000400
        .short  0x0130
        .short  0x0008, 0x0050          /* 10185a */
        .long   0x00004000
        .short  0x0130
        .short  0x0010, 0x0010          /* 101864  PFT */
        .long   PFT
        .short  0x0160
        .short  0x0001, 0x0020          /* 10186e  MMU */
        .long   MMU
        .short  0x0160
        .short  0x0001, 0x0021          /* 101878  SIO */
        .long   SIO
        .short  0x0160
        .short  0x0001, 0x0022          /* 101882  TIMR */
        .long   TIMR
        .short  0x0160
        .short  0x0001, 0x0027          /* 10188c  DISK / FLOP / CALENDAR */
        .long   DISK
        .short  0x0160
        .short  0x0001, 0x0026          /* 101896  RING2 */
        .long   RING2
        .short  0x0160
        .short  0x0001, 0x0025          /* 1018a0  DISP1 */
        .long   DISP1
        .short  0x0160
        .short  0x0001, 0x0024          /* 1018aa  DMA */
        .long   DMA
        .short  0x0160
        .short  0x0080, 0x0080          /* 1018b4  DISP1_MEM */
        .long   DISP1_MEM
        .short  0x0160
        .short  0x0001, 0x0400          /* 1018be  CRASH_RECORD */
        .long   MAP_WIRED + CRASH_$RECORD
        .short  0x0170
        .short  0x0001, 0x0403          /* 1018c8  DUMP */
        .long   MAP_WIRED + DUMP
        .short  0x0170
        .short  0x0001, 0x0404          /* 1018d2  TRAP_PAGE (VA 0; not a RELOC cell) */
        .long   MAP_WIRED + 0x00000000
        .short  0x0170
        .short  0x0002, 0x0405          /* 1018dc  COLD itself (not a RELOC cell) */
        .long   MAP_COLD + MAP_PRIVATE + COLD_LOW
        .short  0x0170
cold_map_kernel_lo_count:
        .short  0x0157, 0x0408          /* 1018e6  kernel, low piece; the count is */
                                        /*         rewritten if the kernel fits */
        .long   MAP_WIRED + OS_PROC     /*         a RELOC cell */
        .short  0x0170
cold_map_kernel_hi_count_ppn:
        .short  0x0000, 0x0000          /* 1018f0  kernel, high piece: count and */
                                        /*         PPN filled by COLD */
        .long   MAP_WIRED + KERNEL_HI_VA /*        a RELOC cell */
        .short  0x0170
        .short  0x0000                  /* 1018fa  end */

/*
 * 0x1018FC: the boot record OS_$INIT receives as its first argument (9
 * longwords, 0x1018FC..0x10191F; d1 and d2 of the entry are its first
 * two), and 0x101908: the diskless record, its second argument (12
 * longwords, 0x101908..0x101937).  They overlap, and the diskless
 * record's last five longwords are COLD's own cells.  All zero in the
 * file except the MMU geometry defaults.
 */
cold_boot_params:
        .long   0, 0, 0                 /* 1018fc */
cold_diskless_info:
        .long   0, 0, 0, 0, 0, 0, 0     /* 101908  the 7 copied longwords */
cold_saved_sp:
        .long   0                       /* 101924 */
cold_mmap_phys:
        .long   0                       /* 101928  MMAP's physical address */
        .long   0, 0                    /* 10192c */
cold_va_shift:
        .short  0x0004                  /* 101934  VA shift (6 on a 68020) */
cold_va_mask:
        .long   0x000fffff              /* 101936  VA mask (0x3fffff on a 68020) */
cold_ptt_entries:
        .short  0x0400                  /* 10193a  PTT entries (0x1000 on a 68020) */

/* 0x10193C..0x101BFC: COLD's stack, zero in the file. */
        .space  0x2c0
cold_stack_top:                         /* 101bfc  the initial SP; COLD + 0x7FC, */
        .space  4                       /*         the map's segment end; then the */
                                        /*         file's pad up to DUMP at 0x800 */

/*
 * The layout this file assumes.  The header's start address and COLD's
 * A5 displacements (COLD_OFF_*) are constants the labels must match;
 * gas can check only the labels ahead of the first relaxable operand
 * here, so the rest is proved by the byte gate (tools/asm_compare.py
 * compares the whole 0x800 bytes with the image, every displacement and
 * every (d16,PC) operand included).
 */
        .ifne   cold_start_entry - COLD - 0x24
        .error  "cold_start_entry is not COLD + 0x24 (the header's start address)"
        .endif
        .ifne   MOVE_TO_PPN - COLD - 0x20
        .error  "MOVE_TO_PPN is not COLD + 0x20"
        .endif

        .size   COLD, . - COLD
